			missing := "file://" + filepath.Join(t.TempDir(), "missing.git")
			if targetKind == "named" {
				testutil.RunGit(t, dir, "remote", "add", "origin", missing)
				writeEnabledSettings(t, dir, `{"enabled":true}`)
			} else {
				testutil.RunGit(t, dir, "remote", "add", "origin", "git@github.com:org/main-repo.git")
				writeEnabledSettings(t, dir,
					`{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"org/checkpoints"}}}`)
				redirectGitURL(t, dir, "git@github.com:org/checkpoints.git", missing)
			}
			warnings := enterPrePushFixture(t, dir)

			require.NoError(t, NewManualCommitStrategy().prePushWithMetadataThreshold(
				context.Background(), "origin", false, shrinkTestThreshold,
			))
			assert.Equal(t, tip, readTip(t, repo), "a failed cleanup must not move the local ref")
			assertSingleCleanupWarning(t, warnings)
		})
	}
}

func TestPrePush_MetadataScanTimeoutSkipsCheckpointPush(t *testing.T) {
	dir, repo, _, _, tip := bloatedV1Fixture(t)
	bare := t.TempDir()
	testutil.RunGit(t, dir, "init", "--bare", bare)
	testutil.RunGit(t, dir, "remote", "add", "origin", bare)
	writeEnabledSettings(t, dir, `{"enabled":true}`)
	warnings := enterPrePushFixture(t, dir)
	previous := metadataScanTimeout
	metadataScanTimeout = time.Nanosecond
	t.Cleanup(func() { metadataScanTimeout = previous })

	require.NoError(t, NewManualCommitStrategy().prePushWithMetadataThreshold(
		context.Background(), "origin", false, shrinkTestThreshold,
	))
	assert.Equal(t, tip, readTip(t, repo))
	assertBareHasNoV1(t, bare)
	assertSingleCleanupWarning(t, warnings)
	assert.Contains(t, warnings.String(), "timed out")
	assert.NotContains(t, warnings.String(), "signal: killed")
}

func TestPrePush_MultipleMergeBasesSkipsCheckpointPush(t *testing.T) {
	dir, repo, _, _, bloatedTip := bloatedV1Fixture(t)
	left, right := crissCrossV1(t, repo, bloatedTip)
	bare := pushV1ToBare(t, dir, right)
	setV1Tip(t, repo, left)
	writeEnabledSettings(t, dir, `{"enabled":true}`)
	warnings := enterPrePushFixture(t, dir)

	require.NoError(t, NewManualCommitStrategy().prePushWithMetadataThreshold(
		context.Background(), "origin", false, shrinkTestThreshold,
	))
	assert.Equal(t, left, readTip(t, repo))
	assert.Equal(t, right.String(), bareV1(t, bare), "the checkpoint push must be skipped")
	assertSingleCleanupWarning(t, warnings)
	assert.Contains(t, warnings.String(), "multiple merge bases")

	// The OPF rewrite reconciles the same history. Its cleanup failure must be
	// distinguishable from OPF's privacy failures so the push is not aborted.
	_, err := rewriteUnpushedV1WithOPF(context.Background(), repo, "origin", shrinkTestThreshold)
	var cleanupErr *metadataCleanupError
	require.ErrorAs(t, err, &cleanupErr)
	assert.False(t, metadataCleanupAbortsPush(err))
}

func TestPrePush_ReplaySuffixOverLimitSkipsCheckpointPush(t *testing.T) {
	dir, repo, _, _, sharedTip := bloatedV1Fixture(t)
	localTip := sharedTip
	for i := range MaxCommitTraversalDepth + 1 {
		localTip = appendCheckpointFiles(t, repo, localTip, "Checkpoint: local suffix", map[string][]byte{
			"ff/ffffffffff/0/metadata.json": []byte(fmt.Sprintf(`{"checkpoint_id":"%012x"}`, i) + "\n"),
		})
	}
	repairedRemoteTip, err := newMetadataRewriter(
		context.Background(), repo, shrinkTestThreshold,
	).rewriteHistory(sharedTip)
	require.NoError(t, err)
	bare := pushV1ToBare(t, dir, repairedRemoteTip)
	setV1Tip(t, repo, localTip)
	writeEnabledSettings(t, dir, `{"enabled":true}`)
	warnings := enterPrePushFixture(t, dir)

	require.NoError(t, NewManualCommitStrategy().prePushWithMetadataThreshold(
		context.Background(), "origin", false, shrinkTestThreshold,
	))
	assert.Equal(t, localTip, readTip(t, repo))
	assert.Equal(t, repairedRemoteTip.String(), bareV1(t, bare))
	assertSingleCleanupWarning(t, warnings)
	assert.Contains(t, warnings.String(), fmt.Sprintf("commit chain exceeded %d commits", MaxCommitTraversalDepth))
}

func TestPrePush_OversizedShallowBoundaryStillAborts(t *testing.T) {
	dir, _, _, _, tip := bloatedV1Fixture(t)
	baredir := pushV1ToBare(t, dir, tip)
	cloneDir := filepath.Join(t.TempDir(), "shallow")
	testutil.RunGit(t, dir, "clone", "--depth=2", "--branch", paths.MetadataBranchName, "file://"+baredir, cloneDir)
	emptyRemote := t.TempDir()
	testutil.RunGit(t, cloneDir, "init", "--bare", emptyRemote)
	testutil.RunGit(t, cloneDir, "remote", "set-url", "origin", emptyRemote)
	writeEnabledSettings(t, cloneDir, `{"enabled":true}`)
	warnings := enterPrePushFixture(t, cloneDir)
	shallowRepo, err := git.PlainOpen(cloneDir)
	require.NoError(t, err)
	t.Cleanup(func() { _ = shallowRepo.Close() })

	err = NewManualCommitStrategy().prePushWithMetadataThreshold(
		context.Background(), "origin", false, shrinkTestThreshold,
	)
	var shallowErr *shallowMetadataRepairError
	require.ErrorAs(t, err, &shallowErr)
	assert.Equal(t, tip, readTip(t, shallowRepo))
	assertBareHasNoV1(t, emptyRemote)
	assert.Empty(t, warnings.String(), "an aborted push reports through the returned error")
}

func writeEnabledSettings(t *testing.T, dir, content string) {
	t.Helper()
	testutil.WriteFile(t, dir, ".entire/settings.json", content+"\n")
}

// enterPrePushFixture moves into dir and captures cleanup warnings. Callers
// cannot run in parallel: pre-push resolves the repository from the CWD.
func enterPrePushFixture(t *testing.T, dir string) *bytes.Buffer {
	t.Helper()
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()
	var warnings bytes.Buffer
	previous := metadataCleanupWarningWriter
	metadataCleanupWarningWriter = &warnings
	t.Cleanup(func() { metadataCleanupWarningWriter = previous })
	return &warnings
}

func assertSingleCleanupWarning(t *testing.T, warnings *bytes.Buffer) {
	t.Helper()
	assert.Equal(t, 1, bytes.Count(warnings.Bytes(), []byte("\n")), "want exactly one warning line, got %q", warnings.String())
	assert.Contains(t, warnings.String(), "[entire] Warning: skipped checkpoint push")
}

func assertBareHasNoV1(t *testing.T, bare string) {
	t.Helper()
	_, err := os.Stat(filepath.Join(bare, "refs", "heads", paths.MetadataBranchName))
	assert.True(t, os.IsNotExist(err), "the checkpoint branch must not be pushed")
	packed, err := os.ReadFile(filepath.Join(bare, "packed-refs"))
	if err == nil {
		assert.NotContains(t, string(packed), paths.MetadataBranchName)
	}
}

// crissCrossV1 builds two checkpoint tips on top of base whose histories have
// two merge bases.
func crissCrossV1(t *testing.T, repo *git.Repository, base plumbing.Hash) (left, right plumbing.Hash) {
	t.Helper()
	aFile := map[string][]byte{"a1/aaaaaaaaaa/0/metadata.json": []byte(`{"checkpoint_id":"a1aaaaaaaaaa"}` + "\n")}
	bFile := map[string][]byte{"b1/bbbbbbbbbb/0/metadata.json": []byte(`{"checkpoint_id":"b1bbbbbbbbbb"}` + "\n")}
	a := appendCheckpointFiles(t, repo, base, "Checkpoint: a", aFile)
	b := appendCheckpointFiles(t, repo, base, "Checkpoint: b", bFile)
	union := readCommit(t, repo, appendCheckpointFiles(t, repo, a, "union", bFile)).TreeHash
	left = makeOrphanCommit(t, repo, union, []plumbing.Hash{a, b}, "Checkpoint: left merge")
	right = makeOrphanCommit(t, repo, union, []plumbing.Hash{b, a}, "Checkpoint: right merge")
	return left, right
}

