// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
// initializing cmd.Env from os.Environ() if nil.
// targetDir runs cmd in dir. Git exports GIT_DIR to hooks and it overrides
// cmd.Dir, so an explicit directory must drop the inherited repo selectors.
func targetDir(cmd *exec.Cmd, dir string) {
	if dir == "" {
		return
	}
	cmd.Dir = dir
	if cmd.Env == nil {
		cmd.Env = os.Environ()
	}
	cmd.Env = gitrepo.WithoutRepoOverrides(cmd.Env)
}

func disableTerminalPrompt(cmd *exec.Cmd) {
	if cmd.Env == nil {
		cmd.Env = os.Environ()
	}
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
}
